ALTER TABLE public.profile_private ADD COLUMN gender_other text;
ALTER TABLE public.profiles ADD COLUMN learning_interests text[] NOT NULL DEFAULT '{}';
ALTER TABLE public.plans ADD COLUMN genre text NOT NULL DEFAULT 'outdoors';
ALTER TABLE public.plans ADD COLUMN activity text NOT NULL DEFAULT 'co-working';
ALTER TABLE public.plans ADD COLUMN image_url text;
ALTER TABLE public.plans ADD COLUMN required_level text NOT NULL DEFAULT 'any' CHECK (required_level IN ('any','beginner','intermediate','advanced'));
CREATE TABLE public.user_settings (user_id uuid PRIMARY KEY REFERENCES public.profiles(id) ON DELETE CASCADE, demo_plus boolean NOT NULL DEFAULT false);
GRANT SELECT,INSERT,UPDATE,DELETE ON public.user_settings TO authenticated;
GRANT ALL ON public.user_settings TO service_role;
ALTER TABLE public.user_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own settings" ON public.user_settings FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.interest_levels (user_id uuid REFERENCES public.profiles(id) ON DELETE CASCADE, interest text NOT NULL, level text NOT NULL DEFAULT 'any' CHECK (level IN ('any','beginner','intermediate','advanced')), PRIMARY KEY(user_id,interest));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.interest_levels TO authenticated;
GRANT ALL ON public.interest_levels TO service_role;
ALTER TABLE public.interest_levels ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read interest levels" ON public.interest_levels FOR SELECT TO authenticated USING (true);
CREATE POLICY "own interest levels" ON public.interest_levels FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE FUNCTION public.people_blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)); $$;
REVOKE ALL ON FUNCTION public.people_blocked(uuid,uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.people_blocked(uuid,uuid) TO authenticated,service_role;
CREATE FUNCTION public.validate_plan_level() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.required_level <> 'any' AND (TG_OP='INSERT' OR NEW.required_level IS DISTINCT FROM OLD.required_level) AND NOT EXISTS(SELECT 1 FROM public.user_settings WHERE user_id=NEW.host_id AND demo_plus) THEN RAISE EXCEPTION 'Tagalong Plus is required to set a proficiency level'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_plan_level BEFORE INSERT OR UPDATE ON public.plans FOR EACH ROW EXECUTE FUNCTION public.validate_plan_level();
CREATE TABLE public.saved_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, name text NOT NULL, filters jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.saved_alerts TO authenticated;
GRANT ALL ON public.saved_alerts TO service_role;
ALTER TABLE public.saved_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "own saved alerts" ON public.saved_alerts FOR ALL TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE TABLE public.notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, plan_id uuid REFERENCES public.plans(id) ON DELETE CASCADE, alert_id uuid REFERENCES public.saved_alerts(id) ON DELETE CASCADE, title text NOT NULL, read boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(plan_id,alert_id));
GRANT SELECT,UPDATE,DELETE ON public.notifications TO authenticated;
GRANT ALL ON public.notifications TO service_role;
ALTER TABLE public.notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "read own notifications" ON public.notifications FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE POLICY "update own notifications" ON public.notifications FOR UPDATE TO authenticated USING(user_id=auth.uid()) WITH CHECK(user_id=auth.uid());
CREATE POLICY "delete own notifications" ON public.notifications FOR DELETE TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.alert_matches(p public.plans,f jsonb) RETURNS boolean LANGUAGE plpgsql STABLE SET search_path=public AS $$ DECLARE hour integer; amount numeric; BEGIN
hour:=extract(hour from p.starts_at AT TIME ZONE COALESCE(NULLIF(f->>'timezone',''),'UTC')); amount:=p.base_price;
IF COALESCE(f->>'city','')<>'' AND lower(p.city)<>lower(f->>'city') THEN RETURN false; END IF;
IF COALESCE(f->>'date','')<>'' AND (p.starts_at AT TIME ZONE COALESCE(NULLIF(f->>'timezone',''),'UTC'))::date::text<>f->>'date' THEN RETURN false; END IF;
IF COALESCE(f->>'genre','')<>'' AND p.genre<>f->>'genre' THEN RETURN false; END IF;
IF COALESCE(f->>'activity','')<>'' AND lower(p.activity)<>lower(f->>'activity') THEN RETURN false; END IF;
IF COALESCE(f->>'audience','')<>'' AND p.audience<>f->>'audience' THEN RETURN false; END IF;
IF COALESCE(f->>'level','')<>'' AND p.required_level<>f->>'level' THEN RETURN false; END IF;
IF COALESCE((f->>'allAbilities')::boolean,false) AND p.required_level<>'any' THEN RETURN false; END IF;
IF COALESCE((f->>'stepFree')::boolean,false) AND NOT p.step_free THEN RETURN false; END IF;
IF COALESCE((f->>'daytime')::boolean,false) AND NOT(hour>=7 AND hour<17) THEN RETURN false; END IF;
IF COALESCE(f->>'time','')='morning' AND NOT(hour>=5 AND hour<12) THEN RETURN false; END IF;
IF COALESCE(f->>'time','')='afternoon' AND NOT(hour>=12 AND hour<17) THEN RETURN false; END IF;
IF COALESCE(f->>'time','')='evening' AND NOT(hour>=17 AND hour<22) THEN RETURN false; END IF;
IF COALESCE(f->>'time','')='late' AND NOT(hour>=22 OR hour<5) THEN RETURN false; END IF;
IF COALESCE(f->>'price','')='free' AND amount<>0 THEN RETURN false; END IF;
IF COALESCE(f->>'price','')='under10' AND NOT(amount>0 AND amount<10) THEN RETURN false; END IF;
IF COALESCE(f->>'price','')='10to30' AND NOT(amount>=10 AND amount<30) THEN RETURN false; END IF;
IF COALESCE(f->>'price','')='30to60' AND NOT(amount>=30 AND amount<60) THEN RETURN false; END IF;
IF COALESCE(f->>'price','')='60plus' AND amount<60 THEN RETURN false; END IF;
RETURN true; END $$;
CREATE FUNCTION public.notify_plan_alerts() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
INSERT INTO public.notifications(user_id,plan_id,alert_id,title) SELECT a.user_id,NEW.id,a.id,a.name||': '||NEW.title FROM public.saved_alerts a WHERE a.user_id IS DISTINCT FROM NEW.host_id AND NOT public.people_blocked(a.user_id,NEW.host_id) AND NEW.starts_at>now() AND public.alert_matches(NEW,a.filters) AND (COALESCE(a.filters->>'level','')='' OR EXISTS(SELECT 1 FROM public.user_settings s WHERE s.user_id=a.user_id AND s.demo_plus)); RETURN NEW; END $$;
CREATE TRIGGER notify_plan_alerts AFTER INSERT ON public.plans FOR EACH ROW EXECUTE FUNCTION public.notify_plan_alerts();
CREATE TABLE public.direct_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), sender_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, body text NOT NULL CHECK(char_length(body) BETWEEN 1 AND 2000), read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), CHECK(sender_id<>recipient_id));
GRANT SELECT,INSERT ON public.direct_messages TO authenticated;
GRANT ALL ON public.direct_messages TO service_role;
ALTER TABLE public.direct_messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "participants read messages" ON public.direct_messages FOR SELECT TO authenticated USING ((sender_id=auth.uid() OR recipient_id=auth.uid()) AND NOT public.people_blocked(sender_id,recipient_id));
CREATE POLICY "sender sends messages" ON public.direct_messages FOR INSERT TO authenticated WITH CHECK(sender_id=auth.uid() AND NOT public.people_blocked(sender_id,recipient_id));
CREATE INDEX direct_messages_sender ON public.direct_messages(sender_id,created_at);
CREATE INDEX direct_messages_recipient ON public.direct_messages(recipient_id,created_at);
ALTER PUBLICATION supabase_realtime ADD TABLE public.direct_messages,public.notifications;
CREATE FUNCTION public.similar_people(_city text,_interests text[],_activity text DEFAULT '',_level text DEFAULT '') RETURNS SETOF public.profiles LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.* FROM public.profiles p WHERE auth.uid() IS NOT NULL AND p.id<>auth.uid() AND p.onboarded AND NOT public.people_blocked(auth.uid(),p.id) AND lower(p.home_city)=lower(_city) AND p.interests && _interests AND (_level='' OR _level='any' OR EXISTS(SELECT 1 FROM public.interest_levels l WHERE l.user_id=p.id AND l.interest=_activity AND l.level=_level)) ORDER BY cardinality(ARRAY(SELECT unnest(p.interests) INTERSECT SELECT unnest(_interests))) DESC LIMIT 12; $$;
REVOKE ALL ON FUNCTION public.similar_people(text,text[],text,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.similar_people(text,text[],text,text) TO authenticated;